19	  final _controller = StreamController<VaultStatus>.broadcast();
20	
21	  /// Controls what the NEXT `authenticate()` call resolves to. Defaults to
22	  /// `false` (a quiet decline), matching `app_router_test.dart`'s own
23	  /// default so a bare `pumpWidget` never silently unlocks.
24	  bool authenticateSucceeds = false;
25	
26	  /// Lets a test hold `authenticate()` unresolved to inspect a mid-flight
27	  /// frame before letting it settle.
28	  Completer<void>? authenticateGate;
29	
30	  int authenticateCallCount = 0;
31	
32	  /// The one PIN `submitPin()` treats as "stored" — `null` means no PIN
33	  /// has been stored yet, matching `VaultRepositoryImpl`'s own set-on-
34	  /// first-use behavior (spec-2-2 Design Notes).
35	  String? storedPin;
36	
37	  int submitPinCallCount = 0;
38	
39	  @override
40	  VaultStatus get currentStatus => _status;
41	
42	  @override
43	  Stream<VaultStatus> get statusStream => _controller.stream;
44	
45	  @override
46	  Future<Either<Failure, Unit>> authenticate() async {
47	    authenticateCallCount += 1;
48	    final gate = authenticateGate;
49	    if (gate != null) {
50	      await gate.future;
51	    }
52	    if (authenticateSucceeds) {
53	      _status = VaultStatus.unlocked;
54	      _controller.add(_status);
55	      return right(unit);
56	    }
57	    return left(
58	      const Failure.malformedResponse(message: 'fake: biometrics declined'),
59	    );
60	  }
61	
62	  @override
63	  Future<Either<Failure, Unit>> submitPin(String pin) async {
64	    submitPinCallCount += 1;
65	    if (storedPin == null) {
66	      storedPin = pin;
67	      _status = VaultStatus.unlocked;
68	      _controller.add(_status);
69	      return right(unit);
70	    }
71	    if (storedPin == pin) {
72	      _status = VaultStatus.unlocked;
73	      _controller.add(_status);
74	      return right(unit);
75	    }
76	    return left(
77	      const Failure.malformedResponse(message: 'fake: PIN mismatch'),
78	    );
79	  }
80	
81	  @override
82	  Future<void> dispose() => _controller.close();
83	}
