15	/// Owns the one broadcast [VaultStatus] stream the epic's AD-14 seam
16	/// requires. Covers the I/O matrix (spec-2-1 + spec-2-2):
17	/// - biometrics succeed -> [VaultStatus.unlocked] emitted, `Right(unit)`.
18	/// - biometrics fail/cancelled/unavailable (`authenticate()` returns
19	///   `false`, or throws `LocalAuthException`, including any OS lockout) ->
20	///   status stays [VaultStatus.locked], `Left(Failure.
21	///   malformedResponse(...))` — every one of those cases routes the caller
22	///   to [submitPin] next (spec-2-2), with no code-specific branch needed
23	///   here since the generic catches below already cover lockout.
24	/// - [submitPin], no PIN stored yet -> stores it, [VaultStatus.unlocked]
25	///   emitted, `Right(unit)`.
26	/// - [submitPin], stored PIN matches -> [VaultStatus.unlocked] emitted,
27	///   `Right(unit)`.
28	/// - [submitPin], stored PIN mismatch -> status stays locked, `Left(Failure.
29	///   malformedResponse(...))`, always retryable (no attempt cap).
30	///
31	/// Zero network calls anywhere in this class (Boundaries: "Vault makes zero
32	/// network calls") and never produces [Failure.authInvalid] (Boundaries:
33	/// reserved for password login) — every failure branch below maps only to
34	/// [Failure.malformedResponse]. The PIN is compared as a plain string
35	/// (Design Notes: `flutter_secure_storage` already encrypts at rest;
36	/// `package:crypto` isn't a pinned dependency) stored under [_pinStorageKey]
37	/// via the same [FlutterSecureStorage] instance
38	/// `SecureStorageAccessTokenProvider` uses for the access/refresh tokens.
39	class VaultRepositoryImpl implements VaultRepository {
40	  VaultRepositoryImpl({
41	    required LocalAuthentication localAuthentication,
42	    required FlutterSecureStorage secureStorage,
43	  }) : _localAuthentication = localAuthentication,
44	       _secureStorage = secureStorage;
45	
46	  static const _pinStorageKey = 'vault_pin';
47	
48	  final LocalAuthentication _localAuthentication;
49	  final FlutterSecureStorage _secureStorage;
50	  final StreamController<VaultStatus> _statusController =
51	      StreamController<VaultStatus>.broadcast();
52	
53	  /// The last status emitted. Starts at [VaultStatus.locked] — not
54	  /// nullable, see [VaultStatus]'s own doc — so [currentStatus] is correct
55	  /// synchronously from construction, with no async warm-up step.
56	  VaultStatus _lastStatus = VaultStatus.locked;
57	
58	  @override
59	  VaultStatus get currentStatus => _lastStatus;
60	
61	  @override
62	  Stream<VaultStatus> get statusStream {
63	    // Same `Stream.multi` replay-to-late-listeners rationale as
64	    // `SessionRepositoryImpl.statusStream`: a listener that subscribes
65	    // after construction (but before any [authenticate] call) still
66	    // immediately sees the cached [_lastStatus] ([VaultStatus.locked])
67	    // rather than nothing until the next emission.
68	    return Stream<VaultStatus>.multi((controller) {
69	      controller.add(_lastStatus);
70	      final subscription = _statusController.stream.listen(
71	        controller.add,
72	        onError: controller.addError,
73	        onDone: controller.close,
74	      );
75	      controller.onCancel = subscription.cancel;
76	    }, isBroadcast: true);
77	  }
78	
79	  void _emit(VaultStatus status) {
80	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
81	    // an in-flight `authenticate()` call — mirrors
82	    // `SessionRepositoryImpl._emit`'s own guard.
83	    if (_statusController.isClosed) {
84	      return;
85	    }
86	    _lastStatus = status;
87	    _statusController.add(status);
88	  }
89	
90	  @override
91	  Future<Either<Failure, Unit>> authenticate() async {
92	    try {
93	      // `biometricOnly: true` (Boundaries/Design Notes) — never lets the
94	      // OS's own device-passcode UI satisfy this call, which would bypass
95	      // Cerne's own PIN screen (Story 2.2) entirely.
96	      // `persistAcrossBackgrounding: true` so a backgrounding mid-prompt
97	      // (e.g. an incoming call) retries on foreground instead of failing
98	      // outright.
99	      final success = await _localAuthentication.authenticate(
100	        localizedReason: 'Autentique-se para acessar o Cerne',
101	        biometricOnly: true,
102	        persistAcrossBackgrounding: true,
103	      );
104	      if (success) {
105	        _emit(VaultStatus.unlocked);
106	        return right(unit);
107	      }
108	      // A `false` result (declined/unavailable, no exception) — status
109	      // stays `locked`; never `Failure.authInvalid` (Boundaries: reserved
110	      // for password login).
111	      return left(
112	        const Failure.malformedResponse(
113	          message: 'Biometric authentication was not successful',
114	        ),
115	      );
116	    } on LocalAuthException catch (error) {
117	      // Covers cancellation, no enrolled biometrics, hardware unavailable,
118	      // etc. (RNF09: never let a platform exception escape unmapped).
119	      return left(Failure.malformedResponse(message: error.toString()));
120	    } catch (error) {
121	      // Any other thrown platform exception (e.g. the plugin's channel
122	      // itself failing) must never escape unmapped either (RNF09) — fail
123	      // closed, same as the documented `LocalAuthException` branch above,
124	      // mirroring `SessionRepositoryImpl.restoreSession()`'s own plain
125	      // `catch`.
126	      return left(Failure.malformedResponse(message: error.toString()));
127	    }
128	  }
129	
130	  @override
131	  Future<Either<Failure, Unit>> submitPin(String pin) async {
132	    try {
133	      final storedPin = await _secureStorage.read(key: _pinStorageKey);
134	      // No PIN-creation screen exists anywhere in `docs/input/` (Design
135	      // Notes) — the first ever `submitPin` call sets the stored PIN
136	      // instead of comparing against one.
137	      if (storedPin == null) {
138	        await _secureStorage.write(key: _pinStorageKey, value: pin);
139	        _emit(VaultStatus.unlocked);
140	        return right(unit);
141	      }
142	      if (storedPin == pin) {
143	        _emit(VaultStatus.unlocked);
144	        return right(unit);
145	      }
146	      // Mismatch — status stays `locked`, no attempt cap (Boundaries: "PIN
147	      // has no attempt cap — always retryable"); never `Failure.authInvalid`
148	      // (reserved for password login), same rationale as `authenticate()`.
149	      return left(
150	        const Failure.malformedResponse(
151	          message: 'PIN did not match the stored PIN',
152	        ),
153	      );
154	    } catch (error) {
155	      // A thrown platform exception from the secure-storage channel must
156	      // never escape unmapped either (RNF09) — fail closed, same as
157	      // `authenticate()`'s own plain `catch`.
158	      return left(Failure.malformedResponse(message: error.toString()));
159	    }
160	  }
161	
162	  @override
163	  Future<void> dispose() async {
164	    await _statusController.close();
165	  }
166	}
